INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (79, 65, 'NAMES-EXISTING', 'TERM-001', 'Re-read in the persisted PDF of REF-01010 (Uganda, The Building Control (Accessibility Standards for Persons with Disabilities) Code, 2019, Part II, section 12(3)(a); plain extraction retrieval-log/session_2026-10-30-d4-ramp-term-adjudication/REF-01010.plain.txt): ''A ramp provided under this Code shall— (a) have a gradient measured along the centre line, that is not steeper than 1:12 as prescribed in Figure 10 in the Schedule;''. The phrase locates where the slope is taken (the centre line of the ramp); it adds no concept. ''Gradient'' is the code''s word for the slope of the ramp, which is TERM-001 (''Slope of an accessible ramp expressed as ratio or percentage''). Owner ruling 2026-10-29 (third), observed_terms 65: ''It names a term we have — All it does is tell where the ramp slope is to be calculated from, i.e. the middle of the ramp. The gradient is another for the slope.'' [ASSUMPTION: the term meant is TERM-001, the only held term that is a ramp''s slope — basis: its definition]. Ledger: references/project-standards.md, ''Owner rulings 2026-10-29 (third)''.', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (80, 70, 'NAMES-EXISTING', 'TERM-089', 'Re-read in the persisted PDF of REF-01015 (Irish Technical Guidance Document M, clause 1.1.3.4 ''Ramped access routes''; plain extraction retrieval-log/session_2026-10-30-d4-ramp-term-adjudication/REF-01015.plain.txt). The clause opens ''The following guidance applies to ramped access routes in addition to the general guidance in 1.1.3.1 above.'' and continues ''For the purpose of this guidance, a gradient of 1:20 or steeper is considered to be a ramp. Ramped access routes should be designed to have the shallowest gradient practical. The preferred maximum gradient is 1:20 but where site specific constraints require it, ramps not steeper than 1:12 may be provided if individual flights are not longer than 2000 mm.'' The stored context_quote is the second sentence of that passage and does not itself contain the phrase (observation_verbatim_audit reports this row); the phrase''s evidence is the clause heading and the sentences on either side. The clause treats the ramped access route as the ramp, with its landings and widths; the head of the phrase is ramp, TERM-089. ''Access route'' is the route through a building and is no part of the term. Owner ruling 2026-10-29 (third), observed_terms 70: ''It names a term we have — ramped access route = ramp. access route is about procession throughout a building''. SOURCE-IDENTITY NOTE: REF-01015''s persisted PDF is the 2010 edition of TGD M (ISBN 978-1-4064-2317-4, (c) Government of Ireland 2010), not the 2022 edition the row''s pub_year states; the row''s notes record this. The phrase, the clause number and the quoted sentences are identical in the 2010 and 2022 texts; the clause differs in one word, where the 2010 text cites Table 1 and the 2022 text Table 2 (REF-01018). [ASSUMPTION: the ''='' reads as the phrase''s head being ramp, so TERM-089 — basis: the owner''s gloss]. Ledger: references/project-standards.md, ''Owner rulings 2026-10-29 (third)''.', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (81, 73, 'NAMES-EXISTING', 'TERM-089', 'Re-read in the persisted PDF of REF-01018 (Irish Technical Guidance Document M 2022, clause 1.1.3.4 ''Ramped Access Routes'', printed page 31; plain extraction retrieval-log/session_2026-10-30-d4-ramp-term-adjudication/REF-01018.plain.txt): ''The following guidance applies to ramped access routes in addition to the general guidance in 1.1.3.1 above. For the purpose of this guidance, a gradient of 1:20 or steeper is considered to be a ramp. Ramped access routes should be designed to have the shallowest gradient practical.'' The stored context_quote is the second of those sentences and does not contain the phrase (observation_verbatim_audit reports this row); the phrase is in the sentence before it and the one after. The text layer of this PDF omits the clause heading ''1.1.3.4 Ramped Access Routes''; a render of the page, which shows it, is persisted as retrieval-log/session_2026-10-30-d4-ramp-term-adjudication/REF-01018.pdfpage38-038.png. Same phrase and clause as observation 70, adjudicated the same way. Owner ruling 2026-10-29 (third), observed_terms 73: ''It names a term we have — it is a ramp, and the access route refers to the barrier-free path of travel insofar as it concerns navigating a building''. [ASSUMPTION: the head of the phrase is ramp, so TERM-089, with the access-route reading (the barrier-free path of travel through a building, observation 68) held outside the term — basis: the owner''s gloss on observations 70 and 73]. Ledger: references/project-standards.md, ''Owner rulings 2026-10-29 (third)''.', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication', '2026-10-30 21:06', 'session_2026-10-30-d4-ramp-term-adjudication');